/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dscal = require( '@stdlib/blas/base/dscal' );
var dsymm = require( './../lib/dsymm.js' );


// FIXTURES //

var cll = require( './fixtures/column_major_l_l.json' );
var clu = require( './fixtures/column_major_l_u.json' );
var crl = require( './fixtures/column_major_r_l.json' );
var cru = require( './fixtures/column_major_r_u.json' );

var rll = require( './fixtures/row_major_l_l.json' );
var rlu = require( './fixtures/row_major_l_u.json' );
var rrl = require( './fixtures/row_major_r_l.json' );
var rru = require( './fixtures/row_major_r_u.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dsymm, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 13', function test( t ) {
	t.strictEqual( dsymm.length, 13, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = rll;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dsymm( value, data.side, data.uplo, data.M, data.N, data.alpha, new Float64Array( data.A ), data.lda, new Float64Array( data.B ), data.ldb, data.beta, new Float64Array( data.C ), data.ldc );
		};
	}
});

