tape( 'the function performs the matrix-matrix operation `C = α*A*B + β*C` or `C = α*B*A + β*C` (row-major, left, lower)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;
	var c;

	data = rll;

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	expected = new Float64Array( data.C_out );

	out = dsymm( data.order, data.side, data.uplo, data.M, data.N, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

