tape( 'if either `M` or `N` is `0`, the function returns the third input matrix unchanged (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;
	var c;

	data = rru;

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	expected = new Float64Array( data.C );

	out = dsymm( data.order, data.side, data.uplo, 0, data.N, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	out = dsymm( data.order, data.side, data.uplo, data.M, 0, data.alpha, a, data.lda, b, data.ldb, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

